#!/usr/bin/env node
/**
 * scripts/bootstrap.js
 *
 * Makes a fresh clone runnable with no manual setup:
 *   git clone ... && npm run launch
 *
 * Responsibilities, in order:
 *   1. Ensure a local .env exists with a usable SENTINEL_JWT_SECRET.
 *   2. Ensure the .runtime/ working directories exist.
 *   3. Report what the app will and will not do without a database.
 *
 * SAFETY: a secret is only ever generated when NODE_ENV !== 'production'.
 * In production the secret must be supplied by the platform (machine env var,
 * systemd drop-in, or the secret store). Generating one there would silently
 * invalidate every session on restart and would hide a real misconfiguration.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.resolve(__dirname, '..');
// Everything a user edits lives under config/. .env is written there when the
// folder exists so operators have one place to look.
const CONFIG_DIR = path.join(ROOT, 'config');
const ENV_FILE = fs.existsSync(CONFIG_DIR)
  ? path.join(CONFIG_DIR, '.env')
  : path.join(ROOT, '.env');
const RUNTIME_DIR = path.join(ROOT, '.runtime');
const IS_PROD = process.env.NODE_ENV === 'production';

function log(msg) { console.log(`[BOOTSTRAP] ${msg}`); }
function warn(msg) { console.warn(`[BOOTSTRAP] ${msg}`); }

// Both locations are honoured so an existing root .env is never duplicated into
// config/. New installs get config/.env; existing ones keep what they have.
const ENV_CANDIDATES = [path.join(CONFIG_DIR, '.env'), path.join(ROOT, '.env')];

function secretIn(file) {
  if (!fs.existsSync(file)) return false;
  const line = fs.readFileSync(file, 'utf8')
    .split(/\r?\n/)
    .find(l => l.trim().startsWith('SENTINEL_JWT_SECRET='));
  return Boolean(line) && line.split('=').slice(1).join('=').trim().length >= 32;
}

function hasSecret() {
  if (process.env.SENTINEL_JWT_SECRET && process.env.SENTINEL_JWT_SECRET.length >= 32) return true;
  return ENV_CANDIDATES.some(secretIn);
}

function ensureSecret() {
  if (hasSecret()) {
    log('SENTINEL_JWT_SECRET present.');
    return;
  }

  if (IS_PROD) {
    console.error('');
    console.error('  SENTINEL_JWT_SECRET is not set and NODE_ENV=production.');
    console.error('  Refusing to generate one automatically: a generated secret would');
    console.error('  invalidate all sessions on every restart and mask a deployment error.');
    console.error('');
    console.error('  Set it from your secret store, e.g. on Windows Server:');
    console.error('    [Environment]::SetEnvironmentVariable(\'SENTINEL_JWT_SECRET\', \'<64+ hex chars>\', \'Machine\')');
    console.error('');
    process.exit(1);
  }

  const secret = crypto.randomBytes(64).toString('hex');
  const block =
    '# Generated by scripts/bootstrap.js for local development.\n' +
    '# NOT for production - supply the secret from your secret store there.\n' +
    `SENTINEL_JWT_SECRET=${secret}\n`;

  if (fs.existsSync(ENV_FILE)) {
    fs.appendFileSync(ENV_FILE, '\n' + block, 'utf8');
    log('Appended a development SENTINEL_JWT_SECRET to the existing .env.');
  } else {
    const example = fs.existsSync(path.join(CONFIG_DIR, '.env.example'))
      ? path.join(CONFIG_DIR, '.env.example')
      : path.join(ROOT, '.env.example');
    const seed = fs.existsSync(example)
      ? '# Seeded from .env.example - review before using beyond local development.\n\n'
      : '';
    fs.writeFileSync(ENV_FILE, seed + block, 'utf8');
    log('Created .env with a development SENTINEL_JWT_SECRET.');
  }
  warn('This secret is for local development only. .env is gitignored.');
}

function ensureRuntimeDirs() {
  for (const dir of [RUNTIME_DIR, path.join(RUNTIME_DIR, 'nas_logs'), path.join(ROOT, 'logs')]) {
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
      log(`Created ${path.relative(ROOT, dir)}/`);
    }
  }
}

function reportDegradedMode() {
  const hasPg = Boolean(process.env.PGHOST || process.env.PGUSER || process.env.DATABASE_URL);
  if (hasPg) return;
  console.log('');
  log('No database configured. The app will start and run in degraded mode:');
  console.log('        - metrics, logs and events are held in memory only');
  console.log('        - identity falls back to the local dev user store');
  console.log('        - history does not survive a restart');
  console.log('        To attach one:  docker compose -f tools/validation/docker-compose.validation.yml up -d');
  console.log('        Then:           npm run migrate');
  console.log('');
}

log(`Preparing workspace (NODE_ENV=${process.env.NODE_ENV || 'development'})`);
ensureSecret();
ensureRuntimeDirs();
reportDegradedMode();
log('Ready. Start with: npm run launch');
